import os
import asyncio
from dotenv import load_dotenv

from ragas.llms import llm_factory
from ragas.metrics.collections import Faithfulness, AnswerRelevancy, ContextPrecision, ContextRecall

# 1. Import AsyncOpenAI and LangChain tools
from openai import AsyncOpenAI
from langchain_google_genai import GoogleGenerativeAIEmbeddings
from ragas.embeddings import LangchainEmbeddingsWrapper

# Explicitly point to the .env file
dotenv_path = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '.env'))
load_dotenv(dotenv_path=dotenv_path, override=True)

# 2. THE MAGIC TRICK: Use OpenAI's robust async client, but route it directly to Google!
client = AsyncOpenAI(
    api_key=os.environ.get("GOOGLE_API_KEY"),
    base_url="https://generativelanguage.googleapis.com/v1beta/openai/"
)

# 3. Create the Judge LLM using the perfectly async client
judge_llm = llm_factory("gemini-2.5-flash", client=client)

# 4. Create the Judge Embeddings using LangChain
raw_embeddings = GoogleGenerativeAIEmbeddings(model="gemini-embedding-001")
judge_embeddings = LangchainEmbeddingsWrapper(raw_embeddings)

async def run_modern_eval():
    faithfulness = Faithfulness(llm=judge_llm)
    answer_relevancy = AnswerRelevancy(llm=judge_llm, embeddings=judge_embeddings)
    context_recall = ContextRecall(llm=judge_llm)
    context_precision = ContextPrecision(llm=judge_llm)

